#!/usr/bin/env bash\nset -e\n\n# Build the linter image\ndocker build -t nightly-dockerfile-linter -f src/Dockerfile src > /dev/null\n\n# Create a temporary Dockerfile with known issues\ncat > /tmp/bad.Dockerfile <<'EOF'\nFROM ubuntu:latest\nADD src /app\nMAINTAINER someone@example.com\nEXPOSE 0\nEOF\n\n# Run the linter inside the container, mounting the bad Dockerfile\noutput=$(docker run --rm -v /tmp/bad.Dockerfile:/Dockerfile nightly-dockerfile-linter /Dockerfile)\n\n# Mock rationale: The linter prints one warning per issue; we verify each expected warning appears.\n\necho "$output" | grep -q "Avoid using the `latest` tag in FROM statements."\necho "$output" | grep -q "Prefer COPY over ADD for copying files."\necho "$output" | grep -q "MAINTAINER instruction is deprecated; use a LABEL instead."\necho "$output" | grep -q "EXPOSE 0 is meaningless; specify a real port."\n\n# Also ensure the success emoji does NOT appear\nif echo "$output" | grep -q "✅ Dockerfile looks good!"; then\n  echo "Unexpected success message found"\n  exit 1\nfi\n\necho "All linter warnings detected as expected."\n
